import fs from "node:fs";
import { CATEGORY_SPRITE_URL } from "./icons/spriteUrl.js";

/** The category icon sprite (DESIGN.md, Icons): a static file named by its content hash, so it caches for a year. Generated by `bun run icons`. */
const SPRITE = new Uint8Array(fs.readFileSync(new URL("./icons/categories.svg", import.meta.url)));

export function iconSpriteResponse(path: string): Response | null {
  if (path !== CATEGORY_SPRITE_URL) return null;
  return new Response(SPRITE, { headers: { "content-type": "image/svg+xml", "cache-control": "public, max-age=31536000, immutable" } });
}
